'use client'

import type { ReactNode } from 'react'
import { Tabs as BaseTabs } from '@base-ui/react/tabs'
import { cn } from '@/lib/utils'
import styles from './Tabs.module.css'

export interface TabItem {
  value: string
  label: ReactNode
  /** The panel shown while this tab is selected. */
  content?: ReactNode
  icon?: ReactNode
  disabled?: boolean
}

export interface TabsProps {
  items: TabItem[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** `underline`: a line under the selected tab. `pills`: a filled segment, for switching views in a toolbar. */
  appearance?: 'underline' | 'pills'
  size?: 'sm' | 'md'
  orientation?: 'horizontal' | 'vertical'
  /** Tabs share the full width equally. */
  isFullWidth?: boolean
  /** Select a tab as soon as it gets focus, rather than on Enter or Space. */
  activateOnFocus?: boolean
  /** Keep hidden panels in the DOM, e.g. to preserve their state. */
  keepMounted?: boolean
  /** Names the tab list when nothing on the page does. */
  'aria-label'?: string
  className?: string
}

export function Tabs({
  items,
  value,
  defaultValue,
  onValueChange,
  appearance = 'underline',
  size = 'md',
  orientation = 'horizontal',
  isFullWidth = false,
  activateOnFocus = false,
  keepMounted = false,
  'aria-label': ariaLabel,
  className,
}: TabsProps) {
  return (
    <BaseTabs.Root
      value={value}
      defaultValue={defaultValue ?? (value === undefined ? items.find((i) => !i.disabled)?.value : undefined)}
      onValueChange={onValueChange && ((v) => onValueChange(v as string))}
      orientation={orientation}
      className={cn(styles.tabs, styles[appearance], styles[size], styles[orientation], isFullWidth && styles.fullWidth, className)}
    >
      <BaseTabs.List className={styles.list} activateOnFocus={activateOnFocus} aria-label={ariaLabel}>
        {items.map((item) => (
          <BaseTabs.Tab key={item.value} value={item.value} disabled={item.disabled} className={styles.tab}>
            {item.icon && (
              <span className={styles.icon} aria-hidden="true">
                {item.icon}
              </span>
            )}
            {item.label}
          </BaseTabs.Tab>
        ))}
        <BaseTabs.Indicator className={styles.indicator} />
      </BaseTabs.List>
      {items.map(
        (item) =>
          item.content !== undefined && (
            <BaseTabs.Panel key={item.value} value={item.value} keepMounted={keepMounted} className={styles.panel}>
              {item.content}
            </BaseTabs.Panel>
          ),
      )}
    </BaseTabs.Root>
  )
}

/* Each size is a control tier (see Foundations/Sizing): height, gap, icon
   and radius come from it. The inline padding is 8px at both sizes, as
   Atlassian Design's tabs: tabs sit side by side with no gap, so two
   labels are 16px apart. The label is 14/20 at both sizes. */
.tabs {
  --tab-height: var(--control-md);
  --tab-pad: var(--space-2);
  --tab-gap: var(--control-md-gap);
  --tab-icon: var(--icon-md);
  --tab-radius: var(--control-md-radius);
  --tab-track-radius: var(--control-md-radius-field);
  display: flex;
  flex-direction: column;
  gap: var(--space-group);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--color-text);
}

.sm {
  --tab-height: var(--control-sm);
  --tab-gap: var(--control-sm-gap);
  --tab-icon: var(--icon-sm);
  --tab-radius: var(--control-sm-radius);
  --tab-track-radius: var(--control-sm-radius-field);
}

.vertical {
  flex-direction: row;
}

.list {
  position: relative;
  z-index: 0;
  display: flex;
}
.vertical .list {
  flex-direction: column;
  align-self: flex-start;
}

.tab {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: var(--tab-gap);
  box-sizing: border-box;
  min-block-size: var(--tab-height);
  margin: 0;
  padding: 0 var(--tab-pad);
  border: 0;
  border-radius: var(--tab-radius);
  background: transparent;
  color: var(--color-text-subtlest);
  font: inherit;
  font-weight: 500;
  white-space: nowrap;
  cursor: var(--cursor-button);
  transition:
    color var(--duration-base),
    background-color var(--duration-base);
}
.vertical .tab {
  justify-content: flex-start;
}
.fullWidth .tab {
  flex: 1;
}

.tab:hover:not([data-disabled]) {
  color: var(--color-text);
}
.tab[data-active] {
  color: var(--color-text);
}
.tab[data-disabled] {
  opacity: 0.5;
  cursor: var(--cursor-disabled);
}
.tab:focus-visible {
  outline: var(--focus-width) solid var(--color-border-focused);
  outline-offset: var(--focus-offset-inset);
}

.icon {
  display: inline-flex;
  font-size: var(--tab-icon);
}

/* underline: a rule under the whole list, and a 2px bar under the
   selected tab that slides between tabs. */
.underline .list {
  box-shadow: inset 0 -1px var(--color-border);
}
/* Atlassian's tab list is pulled out by a tab's padding, so the first
   label lines up with the content under it; the rule starts at the label,
   not at the tab's edge. ::before, so it sits under the indicator. Child
   combinators, so a Tabs nested in a panel keeps its own list. A container
   that clips needs 8px of room on that side, as with Atlassian's. Not at
   full width, where each label is centred in its share of the row. */
.underline.horizontal:not(.fullWidth) > .list {
  margin-inline-start: calc(var(--tab-pad) * -1);
  box-shadow: none;
}
.underline.horizontal:not(.fullWidth) > .list::before {
  content: '';
  position: absolute;
  inset-block-end: 0;
  inset-inline: var(--tab-pad) 0;
  /* Under the tabs, so it never draws through a tab's focus ring. */
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- local stacking under the tabs, not a global layer */
  z-index: -1;
  block-size: var(--border-width);
  background: var(--color-border);
}
.underline.vertical .list {
  box-shadow: inset -1px 0 var(--color-border);
}
.underline .tab[data-active] {
  color: var(--color-text-brand);
}
.underline .indicator {
  position: absolute;
  /* As wide as the label: inset by the tab's padding either side, as
     Atlassian's. */
  inset-inline-start: calc(var(--active-tab-left) + var(--tab-pad));
  inset-block-end: 0;
  inline-size: calc(var(--active-tab-width) - 2 * var(--tab-pad));
  block-size: var(--border-width-selected);
  background: var(--color-background-brand-bold);
  transition:
    inset-inline-start var(--duration-slow),
    inline-size var(--duration-slow);
}
.underline.vertical .indicator {
  inset-inline-start: auto;
  inset-inline-end: 0;
  inset-block-start: var(--active-tab-top);
  inset-block-end: auto;
  inline-size: var(--border-width-selected);
  block-size: var(--active-tab-height);
  transition:
    inset-block-start var(--duration-slow),
    block-size var(--duration-slow);
}

/* pills: a segmented toggle. A --color-background-neutral track, the selected tab a --color-surface-raised
   chip with a hairline edge and a soft shadow. The track is the field-like
   container and the chips sit 2px inside it, so their corner is the
   track's minus 2px: concentric at every preset, never a pill in a track
   that is not one. */
.pills .list {
  gap: var(--space-stack);
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- 2px track inset, below the spacing scale on purpose */
  padding: 2px;
  border-radius: var(--tab-track-radius);
  background: var(--color-background-neutral);
}
.pills.horizontal .list {
  align-self: flex-start;
}
.pills.fullWidth .list {
  align-self: stretch;
}
.pills .tab {
  min-block-size: calc(var(--tab-height) - 4px);
  border-radius: calc(var(--tab-track-radius) - 2px);
  /* --color-text-subtle, not --color-text-subtlest: that is 4.3:1 on the
     --color-background-neutral track, under 4.5. */
  color: var(--color-text-subtle);
}
.pills .tab:hover:not([data-disabled]),
.pills .tab[data-active] {
  color: var(--color-text);
}
.pills .indicator {
  position: absolute;
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- local stacking under the tab label, not a global layer */
  z-index: -1;
  inset-inline-start: var(--active-tab-left);
  inset-block-start: var(--active-tab-top);
  inline-size: var(--active-tab-width);
  block-size: var(--active-tab-height);
  box-sizing: border-box;
  border: 1px solid var(--color-border);
  border-radius: calc(var(--tab-track-radius) - 2px);
  background: var(--color-surface);
  box-shadow: var(--shadow-raised);
  transition:
    inset-inline-start var(--duration-slow),
    inset-block-start var(--duration-slow),
    inline-size var(--duration-slow),
    block-size var(--duration-slow);
}

.panel {
  outline: none;
}
.panel:focus-visible {
  outline: var(--focus-width) solid var(--color-border-focused);
  outline-offset: var(--focus-offset);
  border-radius: var(--radius-sm);
}

@media (pointer: coarse) {
  .tab {
    min-block-size: var(--target-coarse);
  }
}
